 "use_cases": [
  {
   "name": "CalcularComision",
   "description": "Calculates the commission of an operation: flat 0.50 up to 1000.00, otherwise 0.1% rounded half away from zero to 2 decimals, capped at 5.00, plus 1.00 for type INM applied after the cap.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003"
   ],
   "inputs": [
    {
     "name": "monto",
     "type": "decimal(19,4,signed)",
     "column": null,
     "legacy": "monto"
    },
    {
     "name": "tipo",
     "type": "text(var,3,utf8)",
     "column": null,
     "legacy": "tipo"
    }
   ],
   "outputs": [
    {
     "name": "comision",
     "type": "decimal(19,4,signed)",
     "column": null,
     "legacy": "Calcular"
    }
   ],
   "errors": [],
   "ports": [],
   "http_method": "POST",
   "path": "/comisiones/calculos",
   "legacy_program": "ComisionService.Calcular",
   "unit_of_work": null,
   "legacy_message": null
  },
  {
   "name": "RealizarTransferencia",
   "description": "Transfers between two accounts: rejects same account, validates origin (exists, active) and destination (active), checks that the balance covers amount plus commission, debits amount plus commission from the origin, credits only the amount to the destination, registers the transfer with the next sequential number and commits. Returns the status and the outputs as the legacy does on every path.",
   "rules": [
    "RULE-005",
    "RULE-006",
    "RULE-007",
    "RULE-008",
    "RULE-009",
    "RULE-010"
   ],
   "inputs": [
    {
     "name": "cuentaOrigen",
     "type": "text(var,10,utf8)",
     "column": null,
     "legacy": "txtCuentaOrigen"
    },
    {
     "name": "cuentaDestino",
     "type": "text(var,10,utf8)",
     "column": null,
     "legacy": "txtCuentaDestino"
    },
    {
     "name": "monto",
     "type": "decimal(19,4,signed)",
     "column": null,
     "legacy": "txtMonto"
    },
    {
