   "unit_of_work": {
    "begins_at": 34,
    "commits_at": 102,
    "savepoints": [],
    "rollbacks": [
     {
      "legacy_line": 43,
      "outcome": "ORIGEN_NO_EXISTE"
     },
     {
      "legacy_line": 52,
      "outcome": "ORIGEN_INACTIVA"
     },
     {
      "legacy_line": 62,
      "outcome": "DESTINO_NO_EXISTE"
