    },
    {
     "name": "monto",
     "type": "text(var,15,utf8)",
     "column": null,
     "legacy": "lblMonto"
    }
   ],
   "errors": [],
   "ports": [
    "TransferenciaRepository"
   ],
   "http_method": "GET",
   "path": "/comprobantes/{numero}",
   "legacy_program": "Comprobante",
   "unit_of_work": null,
   "legacy_message": null
