using System.Globalization;
using Bancoficticio.Transferencias.Adapters.In.Rest;
using Bancoficticio.Transferencias.Domain.Port;

namespace Bancoficticio.Transferencias.Application;

public sealed class RealizarTransferenciaService(
    CuentaRepository cuentas,
    TransferenciaRepository transferencias,
    UnitOfWork unitOfWork)
{
    public RealizarTransferenciaResponse Execute(RealizarTransferenciaRequest request)
    {
        // Legacy: txtCuentaOrigen.Text.Trim(), txtCuentaDestino.Text.Trim(), decimal.Parse(txtMonto.Text), ddlTipo.SelectedValue
        string? origen = request.CuentaOrigen?.Trim();
        string? destino = request.CuentaDestino?.Trim();
        decimal monto = request.Monto!.Value;
        string? tipo = request.Tipo;

        // RULE-005: same account, no database access, no transaction
        if (origen == destino)
        {
            return Rejected("LA CUENTA DESTINO ES LA MISMA");
        }

        unitOfWork.Begin();

        // RULE-006: origin must exist and be active
        var cuentaOrigen = cuentas.FindByNumero(origen);
        if (cuentaOrigen == null)
        {
            unitOfWork.Rollback();
            return Rejected("CUENTA ORIGEN NO EXISTE");
        }
        string? estado = cuentaOrigen.Estado;
        decimal saldo = cuentaOrigen.Saldo!.Value;
        if (estado != "A")
        {
            unitOfWork.Rollback();
            return Rejected("CUENTA ORIGEN INACTIVA");
        }

        // RULE-007: destination must exist and be active
        if (!cuentas.ExistsActive(destino))
        {
            unitOfWork.Rollback();
            return Rejected("CUENTA DESTINO NO EXISTE");
        }

        // RULE-008: balance must cover amount plus commission
        decimal comision = Calcular(monto, tipo);
        if (saldo < monto + comision)
        {
            unitOfWork.Rollback();
            return Rejected("SALDO INSUFICIENTE");
        }

        // RULE-009: posting
        cuentas.Debit(origen, monto + comision);
        cuentas.Credit(destino, monto);

        // RULE-010: registration
        int numero = transferencias.NextNumero();
        transferencias.Register(numero, origen, destino, monto, comision, tipo);

        unitOfWork.Commit();

        return new RealizarTransferenciaResponse(
            0,
            "TRANSFERENCIA REALIZADA",
            comision.ToString("0.00", CultureInfo.InvariantCulture),
            numero);
    }

    // ComisionService.Calcular (RULE-001..003)
    private static decimal Calcular(decimal monto, string? tipo)
    {
        decimal comision = monto <= 1000m
            ? 0.50m
            : Math.Round(monto * 0.001m, 2, MidpointRounding.AwayFromZero);
        if (comision > 5.00m)
        {
            comision = 5.00m;
        }
        if (tipo == "INM")
        {
            comision += 1.00m;
        }
        return comision;
    }

    private static RealizarTransferenciaResponse Rejected(string mensaje) =>
        new(-1, mensaje, null, null);
}
